const V=T.Vector3;
function mesh(parent,geo,material){const m=new T.Mesh(geo,material);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
function tube(parent,pts,r,material){return mesh(parent,new T.TubeGeometry(new T.CatmullRomCurve3(pts.map(p=>new V(...p))),Math.max(12,pts.length*5),r,5,false),material);}
function oval(parent,pos,scale,material){const m=mesh(parent,new T.SphereGeometry(1,16,12),material);m.position.set(...pos);m.scale.set(...scale);return m;}
// Ring loft: one continuous tapered skin instead of overlapping primitive bodies.
function skin(parent,profile,material,p){const positions=[],cols=[],indices=[],N=28;const base=new T.Color().setHSL(p.hue,.53,.43),light=new T.Color().setHSL((p.hue+.035)%1,.34,.79),mark=new T.Color().setHSL((p.hue+.09)%1,.64,.29);for(let j=0;j<profile.length;j++){const[z,rx,ry,cy=0]=profile[j];for(let k=0;k<=N;k++){const a=k/N*Math.PI*2,x=Math.cos(a)*rx,y=Math.sin(a)*ry;positions.push(x,y+cy,z);const c=base.clone().lerp(light,Math.max(0,-Math.sin(a))*.82);const pat=p.pattern===0?Math.sin(z*13+a*5):p.pattern===1?Math.sin(z*18):Math.sin(a*11+z*4)*Math.cos(z*12);if(pat>.76&&Math.sin(a)>-.2)c.lerp(mark,.62);cols.push(c.r,c.g,c.b);if(j&&k){const q=j*(N+1)+k;indices.push(q,q-1,q-N-2,q,q-N-2,q-N-1);}}}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(positions,3));g.setAttribute('color',new T.Float32BufferAttribute(cols,3));g.setIndex(indices);g.computeVertexNormals();return mesh(parent,g,material);}
function membrane(parent,points,material){const shape=new T.Shape();shape.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)shape.quadraticCurveTo((points[i-1][0]+points[i][0])/2,(points[i-1][1]+points[i][1])/2,points[i][0],points[i][1]);shape.closePath();const g=new T.ShapeGeometry(shape,12);g.rotateX(Math.PI/2);return mesh(parent,g,material);}
export function makeCreature(genome){const p=phenotype(genome),group=new T.Group(),body=new T.Group();group.add(body);const base=new T.Color().setHSL(p.hue,.55,.44),accent=new T.Color().setHSL((p.hue+.09)%1,.52,.7);const solid=new T.MeshStandardMaterial({color:base,roughness:.42,metalness:.12}),skinMat=new T.MeshStandardMaterial({vertexColors:true,roughness:.43,metalness:.08,side:T.DoubleSide}),finMat=new T.MeshStandardMaterial({color:accent,side:T.DoubleSide,roughness:.42,transparent:true,opacity:.92}),lineMat=new T.MeshStandardMaterial({color:base.clone().multiplyScalar(.45),roughness:.6}),glow=new T.MeshStandardMaterial({color:accent,emissive:accent,emissiveIntensity:p.glow*.65,roughness:.3}),eyeMat=new T.MeshStandardMaterial({color:0x071e26,roughness:.13}),white=new T.MeshStandardMaterial({color:0xe8eacc,roughness:.3});const limbs=[];const length=1+p.tail*.12;
 function eyes(z,y,width){for(const side of[-1,1]){oval(body,[side*width,y,z],[.082,.08,.08],white);oval(body,[side*(width+.026),y+.008,z+.045],[.055,.055,.045],eyeMat);oval(body,[side*(width+.04),y+.028,z+.07],[.016,.018,.012],white);}}
 function fin(side,z,span,back){const pivot=new T.Group();pivot.position.set(side*.35,-.05,z);body.add(pivot);const points=[[0,.24],[side*span,-.2],[side*span*.68,-back],[0,-.5]];membrane(pivot,points,finMat);for(let n=1;n<=4;n++)tube(pivot,[[0,0,.15],[side*span*n/5,-.015,-.18],[side*span*n/5,-.02,-back*n/5]],.009,lineMat);pivot.userData.side=side;limbs.push(pivot);return pivot;}
 if(p.body===0){skin(body,[[-1.48,.06,.08],[-1.1,.15,.19],[-.6,.34,.43],[0,.48,.57],[.55,.43,.49],[1,.29,.32],[1.3,.08,.14],[1.34,.015,.07]],skinMat,p);eyes(.93,.2,.275);for(const side of[-1,1]){fin(side,.28,.55+p.fin*.19,.8);for(let n=0;n<3;n++)tube(body,[[side*.33,.32,.66-n*.085],[side*.445,.08,.53-n*.085],[side*.36,-.27,.47-n*.085]],.013,lineMat);tube(body,[[side*.4,.07,.4],[side*.43,.06,0],[side*.25,.03,-.8]],.012,glow);}
 const dorsal=membrane(body,[[0,0],[.25,.8+p.horn*.1],[.75,.42],[1.2,0]],finMat);dorsal.rotation.z=Math.PI/2;dorsal.position.set(0,.42,.1);dorsal.rotation.y=Math.PI/2;
 const tail=new T.Group();tail.position.z=-1.4;body.add(tail);const f=membrane(tail,[[0,0],[-.65,-.75*length],[-.22,-.5*length],[0,-.31],[.22,-.5*length],[.65,-.75*length]],finMat);f.rotation.z=Math.PI/2;tail.userData.tail=true;limbs.push(tail);for(let j=0;j<5;j++)oval(body,[0,.55-j*.018,.25-j*.16],[.025,.027,.035],glow);
 }else if(p.body===1){skin(body,[[-1.4,.08,.08],[-.8,.45,.17],[0,.72,.25],[.8,.55,.24],[1.15,.24,.15],[1.24,.1,.09]],skinMat,p);for(const side of[-1,1]){const wing=fin(side,.5,1.65+p.fin*.22,1.5);wing.position.x=side*.35;for(let n=0;n<4;n++)tube(body,[[side*.2,-.21,.55-n*.16],[side*.4,-.23,.53-n*.16]],.012,lineMat);tube(body,[[side*.3,.02,1],[side*.35,.03,1.45],[side*.17,.04,1.6]],.065,solid);}eyes(.77,.25,.34);const tail=tube(body,[[0,0,-1],[0,-.02,-1.7],[.15,.03,-2.6],[.25,.14,-3.2-p.tail*.2]],.034,solid);tail.userData.tail=true;limbs.push(tail);for(let n=0;n<6;n++)oval(body,[Math.sin(n*2.4)*.4,.24,.55-n*.22],[.027,.014,.035],glow);
 }else if(p.body===2){const pos=[],ix=[],N=48,R=16;for(let j=0;j<=R;j++){const v=j/R*Math.PI*.53;for(let k=0;k<=N;k++){const a=k/N*Math.PI*2,r=Math.sin(v)*(1+.045*Math.sin(a*12)*j/R);pos.push(Math.cos(a)*r,.7*Math.cos(v)+.38,Math.sin(a)*r);if(j&&k){const q=j*(N+1)+k;ix.push(q,q-1,q-N-2,q,q-N-2,q-N-1);}}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(pos,3));geo.setIndex(ix);geo.computeVertexNormals();mesh(body,geo,new T.MeshStandardMaterial({color:base,emissive:accent,emissiveIntensity:.16,transparent:true,opacity:.68,roughness:.18,side:T.DoubleSide,depthWrite:false}));oval(body,[0,.53,0],[.28,.22,.28],glow);for(let n=0;n<12;n++){const a=n*Math.PI/6,pts=[];for(let j=0;j<=8;j++){const v=j/8*Math.PI*.53;pts.push([Math.cos(a)*Math.sin(v),.7*Math.cos(v)+.38,Math.sin(a)*Math.sin(v)]);}tube(body,pts,.012,glow);const strand=tube(body,Array.from({length:9},(_,k)=>[Math.cos(a)*(.84+.05*Math.sin(k+n)),.29-k*(.19+p.tail*.028),Math.sin(a)*.84+Math.sin(k*.8+n)*.1]),n%3===0?.04:.016,finMat);limbs.push(strand);}for(let n=0;n<4;n++){const a=n*Math.PI/2;tube(body,Array.from({length:9},(_,k)=>[Math.cos(a)*(.16+k*.028)+Math.sin(k*1.2)*.07,.4-k*.2,Math.sin(a)*(.16+k*.028)]),.045,glow);}
 }else{skin(body,[[-1.1,.05,.07],[-.8,.58,.23],[-.3,.87,.42,.09],[.35,.87,.43,.09],[.88,.48,.23],[1,.06,.08]],skinMat,p);oval(body,[0,-.13,0],[.77,.18,.96],finMat);skin(body,[[.8,.18,.13],[1.2,.19,.17],[1.5,.23,.19],[1.72,.1,.12],[1.77,.01,.04]],skinMat,p);eyes(1.58,.12,.19);for(const side of[-1,1]){const front=fin(side,.62,.85+p.fin*.14,.6);front.rotation.y=side*-.35;const back=fin(side,-.61,.48,.75);back.position.x=side*.5;back.rotation.y=side*.2;}tube(body,[[0,0,-.9],[0,-.02,-1.3],[.1,.03,-1.6-p.tail*.08]],.06,solid);for(let n=0;n<5;n++){const z=-.68+n*.33,w=.64*Math.sqrt(Math.max(.1,1-z*z));tube(body,[[-w,.28,z],[-w*.5,.45,z+.09],[0,.52,z-.05],[w*.5,.45,z+.09],[w,.28,z]],.014,lineMat);}for(const side of[-1,1])tube(body,[[side*.33,.33,-.7],[side*.39,.48,-.25],[side*.39,.49,.3],[side*.26,.33,.8]],.016,lineMat);
 }
 if(p.body!==2)for(let n=0;n<p.horn;n++){const z=.3-n*.22;tube(body,[[0,p.body===3?.53:.38,z],[0,.65+n*.055,z-.06],[0,.8+n*.06,z-.22]],.026,glow);}
 // Each body allele comes from one parent. Secondary anatomy remains visibly expressed.
 if(p.fusion){if(p.secondary===3){const carapace=oval(body,[0,.23,-.12],[.77,.43,.94],new T.MeshStandardMaterial({color:base.clone().multiplyScalar(.65),roughness:.32,metalness:.3}));for(let n=0;n<5;n++)tube(body,[[-.56,.46,-.7+n*.31],[0,.67,-.76+n*.31],[.56,.46,-.7+n*.31]],.021,glow);}
 if(p.secondary===1)for(const side of[-1,1]){const wing=fin(side,-.1,1.4+p.fin*.18,1.55);wing.position.y=.15;}
 if(p.secondary===2){for(let n=0;n<8;n++){const a=n*Math.PI/4;const limb=tube(body,Array.from({length:9},(_,k)=>[Math.cos(a)*(.55+k*.035),-.15-k*.21,Math.sin(a)*.55+Math.sin(k*.9+n)*.14]),.027,glow);limbs.push(limb);}const veil=oval(body,[0,.3,.05],[.92,.56,1.02],new T.MeshStandardMaterial({color:accent,transparent:true,opacity:.23,side:T.DoubleSide,depthWrite:false,emissive:accent,emissiveIntensity:.15}));}
 if(p.secondary===0){const tail=new T.Group();body.add(tail);tail.position.z=-1.05;tail.userData.tail=true;const blade=membrane(tail,[[0,0],[-.9,-1.1],[-.26,-.7],[0,-.4],[.26,-.7],[.9,-1.1]],finMat);blade.rotation.z=Math.PI/2;limbs.push(tail);}}
 // Alien anatomy is driven by allele values, including serrated fins and sensory eyes.
 for(const side of[-1,1]){for(let n=0;n<2+p.horn;n++){const spike=mesh(body,new T.ConeGeometry(.055,.4+n*.08,5),glow);spike.position.set(side*(.35+n*.1),.35,.15-n*.29);spike.rotation.z=-side*.8;}
 const horn=tube(body,[[side*.3,.25,.65],[side*.42,.7,1],[side*.52,1.05,1.25+genome.horn[side===1?1:0]/500]],.038,glow);for(let n=0;n<Math.max(1,p.eyes-2);n++){oval(body,[side*(.34+n*.09),.3+n*.065,.7-n*.19],[.054,.06,.047],white);oval(body,[side*(.35+n*.09),.32+n*.065,.735-n*.19],[.026,.036,.028],eyeMat);}}
 if(p.pattern>=2){for(let n=0;n<3;n++){const a=n*2.094;tube(body,[[Math.cos(a)*.25,.4,0],[Math.cos(a)*.7,.8,-.7],[Math.cos(a)*.5,.5,-1.5],[0,.1,-2]],.017,glow);}}
 group.scale.setScalar(p.size);group.userData={body,limbs,phenotype:p};return group;
}
export function animateCreature(m,t){const u=m.userData;u.body.rotation.z=Math.sin(t*1.8)*.025;u.limbs.forEach((f,i)=>{if(f.userData.tail)f.rotation.y=Math.sin(t*4)*.13;else if(u.phenotype.body===2){f.rotation.x=Math.sin(t*1.6+i*.5)*.045;f.rotation.z=Math.cos(t*1.3+i)*.04;}else f.rotation.z=Math.sin(t*(u.phenotype.body===1?2:3)+i*.4)*(f.userData.side||1)*(u.phenotype.body===1?.18:.1);});if(u.phenotype.body===2)u.body.scale.set(1+Math.sin(t*2)*.04,1-Math.sin(t*2)*.04,1+Math.sin(t*2)*.04);}
